// EDITAR UNA VEZ tras importar: valores del despliegue que NO son secretos.
// Las claves privadas (GitHub, Claude, clave de servicio de Supabase, Gmail) van en credenciales de n8n, nunca aquí.
return [{ json: {
  github_repo: 'TU-USUARIO/meridiano-motor',                    // repositorio donde corre el motor (GitHub Actions)
  github_rama: 'main',
  supabase_url: 'https://xxxxxxxx.supabase.co',
  hoja_datos_id: 'ID-de-la-hoja-de-Google-Sheets',               // lo que va entre /d/ y /edit en la URL de la hoja
  panel_url: 'https://meridiano-panel.lovable.app',
  correo_direccion: 'direccion@meridiano.com',
  correo_datos: 'datos@meridiano.com',                           // responsable de la hoja de datos (avisos de la carga)
  modelo_ia: 'claude-sonnet-5-5',
  // MODO DEMO (datos ficticios): todos los correos van al buzón de pruebas, con el destinatario real en el asunto.
  // Los correos salen de la cuenta de Gmail conectada en n8n; el buzón de pruebas puede ser esa misma cuenta (con alias +demo).
  modo_demo: true,
  buzon_demo: 'TU-CUENTA+demo@gmail.com',
} }];

// EDITAR ANTES DE LANZAR: qué se audita y con qué modelo.
//  · tipo 'prueba'  → paquete corto con fallos puestos a propósito: comprueba que el flujo funciona. No es la auditoría.
//  · tipo 'diseno'  → paso 05 de FORGEN: especificaciones de los 9 nodos.
//  · tipo 'backlog' → paso 08 de FORGEN: backlog y solución desplegada (paquete pendiente de preparar).
// El modelo auditor debe ser DISTINTO y MÁS CAPAZ que el que generó el diseño (Claude Opus).
const tipo = 'prueba';
const modelo_auditor = 'claude-fable-5-1';

const ARCHIVOS = {
  prueba:  { paquete: 'auditoria/paquete_prueba.md',  rubrica: 'auditoria/rubrica_diseno.md' },
  diseno:  { paquete: 'auditoria/paquete_diseno.md',  rubrica: 'auditoria/rubrica_diseno.md' },
  backlog: { paquete: 'auditoria/paquete_backlog.md', rubrica: 'auditoria/rubrica_backlog.md' },
};
if (!ARCHIVOS[tipo]) throw new Error(`tipo «${tipo}» no válido: usa prueba, diseno o backlog`);
const cfg = $('Configuración').first().json;
return [{ json: { tipo, modelo: modelo_auditor, ...ARCHIVOS[tipo], repo: cfg.github_repo, rama: cfg.github_rama || 'main' } }];

// Junta el paquete y la rúbrica leídos de GitHub (con su versión: el sha del archivo) en la petición al auditor.
// Del archivo de rúbrica solo se usa la sección «## Mensaje de sistema».
const par = $('Parámetros de la auditoría').first().json;
function leer(nodo, ruta) {
  const r = $(nodo).first().json || {};
  if ((r.statusCode || 200) >= 300 || !r.body || !r.body.content) {
    const msg = (r.body && r.body.message) || JSON.stringify(r.body || r).slice(0, 200);
    throw new Error(`No se ha podido leer ${ruta} de GitHub (${r.statusCode || '?'}): ${msg}`);
  }
  return { texto: Buffer.from(r.body.content, 'base64').toString('utf8'), sha: r.body.sha };
}
const paquete = leer('GitHub: leer paquete', par.paquete);
const rubrica = leer('GitHub: leer rúbrica', par.rubrica);
const m = rubrica.texto.match(/## Mensaje de sistema\s*\n([\s\S]*?)(?=\n## |\s*$)/);
if (!m || m[1].trim().length < 200) throw new Error(`La rúbrica ${par.rubrica} no tiene la sección «## Mensaje de sistema»`);
return [{ json: {
  tipo: par.tipo, modelo: par.modelo,
  paquete_ruta: par.paquete, paquete_sha: paquete.sha, rubrica_ruta: par.rubrica, rubrica_sha: rubrica.sha,
  sistema: m[1].trim(), paquete: paquete.texto,
} }];

// Sensor de Govern sobre la respuesta del auditor: debe ser el JSON pedido por la rúbrica. Se guarda SIEMPRE una fila
// (también si falla), con la respuesta tal cual, para que la evidencia no dependa de que el formato sea correcto.
const p = $('Preparar la petición').first().json;
const r = $input.first().json || {};
const VEREDICTOS = ['aprobado', 'aprobado con cambios', 'rechazado'];
const SEV = ['alta', 'media', 'baja'];
const CAMPOS = ['id', 'nodo', 'criterio', 'hallazgo', 'evidencia', 'severidad', 'correccion_propuesta'];
const fila = {
  tipo: p.tipo, modelo: p.modelo, paquete_ruta: p.paquete_ruta, paquete_sha: p.paquete_sha,
  rubrica_ruta: p.rubrica_ruta, rubrica_sha: p.rubrica_sha,
  estado: 'error', veredicto: null, resumen: null, hallazgos: [], puntos_fuertes: [],
  n_altas: 0, n_medias: 0, n_bajas: 0, avisos: [], error: null, respuesta_bruta: null,
  tokens_entrada: null, tokens_salida: null,
};
const b = r.body || {};
if ((r.statusCode || 0) >= 300 || !Array.isArray(b.content)) {
  const e = b.error || {};
  fila.error = `El modelo auditor no respondió (${r.statusCode || 'sin respuesta'}): ${e.message || JSON.stringify(b).slice(0, 300)}`;
  return [{ json: fila }];
}
fila.tokens_entrada = (b.usage || {}).input_tokens ?? null;
fila.tokens_salida = (b.usage || {}).output_tokens ?? null;
const texto = b.content.filter(c => c.type === 'text').map(c => c.text).join('\n').trim();
fila.respuesta_bruta = texto.slice(0, 100000);
const errores = [];
let j = null;
try {
  const ini = texto.indexOf('{'), fin = texto.lastIndexOf('}');
  j = JSON.parse(texto.slice(ini, fin + 1));
} catch (e) { errores.push('la respuesta no es un JSON válido'); }
if (j) {
  if (!VEREDICTOS.includes(j.veredicto)) errores.push(`veredicto «${j.veredicto}» no válido`);
  if (typeof j.resumen !== 'string' || !j.resumen.trim()) errores.push('falta el resumen');
  if (!Array.isArray(j.hallazgos)) errores.push('hallazgos no es una lista');
  else {
    if (j.hallazgos.length > 12) errores.push(`${j.hallazgos.length} hallazgos (máximo 12)`);
    j.hallazgos.forEach((h, i) => {
      const faltan = CAMPOS.filter(c => typeof (h || {})[c] !== 'string' || !h[c].trim());
      if (faltan.length) errores.push(`hallazgo ${i + 1}: faltan ${faltan.join(', ')}`);
      else if (!SEV.includes(h.severidad)) errores.push(`hallazgo ${i + 1}: severidad «${h.severidad}» no válida`);
    });
  }
  if (j.puntos_fuertes !== undefined && !Array.isArray(j.puntos_fuertes)) errores.push('puntos_fuertes no es una lista');
}
if (errores.length) {
  fila.estado = 'formato_invalido';
  fila.error = errores.slice(0, 10).join('; ');
  return [{ json: fila }];
}
const cuenta = s => j.hallazgos.filter(h => h.severidad === s).length;
Object.assign(fila, {
  estado: 'ok', veredicto: j.veredicto, resumen: j.resumen.trim(), hallazgos: j.hallazgos,
  puntos_fuertes: (j.puntos_fuertes || []).slice(0, 3), n_altas: cuenta('alta'), n_medias: cuenta('media'), n_bajas: cuenta('baja'),
});
// Coherencia con la rúbrica (aviso, no invalida: queda registrado para revisarlo)
if (fila.veredicto === 'aprobado' && (fila.n_altas || fila.n_medias)) fila.avisos.push('veredicto «aprobado» con hallazgos altos o medios');
if (fila.veredicto === 'rechazado' && !fila.n_altas) fila.avisos.push('veredicto «rechazado» sin hallazgos altos');
return [{ json: fila }];

// Resumen por correo de la ejecución del auditor (la evidencia completa queda en la tabla auditorias de Supabase).
const f = $('Validar respuesta del auditor').first().json;
const NOMBRE = { prueba: 'PRUEBA del flujo', diseno: 'auditoría del diseño (paso 05)', backlog: 'auditoría del backlog (paso 08)' };
const cab = [`Tipo: ${NOMBRE[f.tipo] || f.tipo}`, `Modelo auditor: ${f.modelo}`,
  `Paquete: ${f.paquete_ruta} (versión ${String(f.paquete_sha || '').slice(0, 7)})`,
  `Rúbrica: ${f.rubrica_ruta} (versión ${String(f.rubrica_sha || '').slice(0, 7)})`];
let asunto, cuerpo;
if (f.estado !== 'ok') {
  asunto = `Meridiano · auditor: ${f.estado === 'error' ? 'el modelo no respondió' : 'respuesta con formato no válido'}`;
  cuerpo = [...cab, '', `Estado: ${f.estado}`, `Detalle: ${f.error}`, '',
    'La ejecución ha quedado registrada en la tabla auditorias con la respuesta tal cual.'].join('\n');
} else {
  asunto = `Meridiano · auditor: ${f.veredicto} (${f.n_altas} altas, ${f.n_medias} medias, ${f.n_bajas} bajas)`;
  const h = f.hallazgos.map(x => `- [${x.severidad.toUpperCase()}] ${x.id} · ${x.nodo} · ${x.criterio}: ${x.hallazgo}\n    Corrección: ${x.correccion_propuesta}`);
  cuerpo = [...cab, '', `VEREDICTO: ${f.veredicto.toUpperCase()}`, f.resumen, '', 'HALLAZGOS', ...(h.length ? h : ['(ninguno)']),
    ...(f.puntos_fuertes.length ? ['', 'PUNTOS FUERTES', ...f.puntos_fuertes.map(x => `- ${x}`)] : []),
    ...(f.avisos.length ? ['', 'AVISOS DE COHERENCIA', ...f.avisos.map(x => `- ${x}`)] : []),
    '', `Tokens: ${f.tokens_entrada} de entrada, ${f.tokens_salida} de salida. Detalle completo en la tabla auditorias.`].join('\n');
}
return [{ json: { asunto, texto: cuerpo } }];
